-muted);text-transform:uppercase}.conversation-toolbar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin:14px 0}.conversation-list{border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}.chat-row{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;text-align:left;padding:14px;border:0;border-bottom:1px solid var(--line);background:var(--surface);color:var(--text)}.chat-row:last-child{border:0}.chat-title{font-weight:600}.chat-preview{color:var(--muted);font-size:11px;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chat-badge{font-size:10px;color:var(--red)}.thread{display:none;margin-top:14px}.thread.show{display:block}.thread-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.bubble{max-width:88%;padding:11px 13px;margin:8px 0;border:1px solid var(--line);border-radius:13px;background:#10151d}.bubble.out{margin-left:auto;background:#13203c;border-color:#2f4f8c}.bubble.deleted{border-color:#64343a;background:#190d10}.bubble-meta{font-size:9px;color:var(--muted);margin-bottom:5px}.bubble-text{white-space:pre-wrap;word-break:break-word}.bubble-media{font-size:10px;color:var(--blue-soft);margin-top:7px}.bubble-media-files{display:grid;gap:7px;margin-top:9px}.media-preview{display:block;width:100%;max-height:320px;object-fit:contain;border:1px solid var(--line);border-radius:10px;background:#050608}.media-download{display:block;padding:10px;border:1px solid var(--line);border-radius:9px;color:var(--blue-soft);text-decoration:none}.deleted-pill{color:#ff9ba4}.archive-note{padding:13px;border:1px solid #624c28;border-radius:11px;background:#191309;color:#d5bd91;font-size:11px;line-height:1.6;margin-top:12px}
@media(max-width:520px){.wrap{padding-left:18px;padding-right:18px}.head{height:72px}.brand{font-size:22px}.intro{padding-top:30px}.metrics{grid-template-columns:repeat(3,1fr)}.metric{display:block;padding:14px 10px;border-right:1px solid var(--line);border-bottom:0}.metric-name{font-size:8px}.metric-value{font-size:21px;text-align:left;margin-top:5px}.profile-preview{grid-template-columns:62px minmax(0,1fr)}.profile-preview img{width:62px;height:62px}.save-state{grid-column:2}.avatar-editor{grid-template-columns:72px minmax(0,1fr)}.avatar-preview{width:72px;height:72px}.save-dock{grid-template-columns:1fr;margin-inline:-4px}.save-dock .btn{width:100%}.home-site{grid-template-columns:40px minmax(0,1fr) auto}.archive-summary{grid-template-columns:repeat(2,1fr)}.archive-number:nth-child(2){border-right:0}.archive-number:nth-child(-n+2){border-bottom:1px solid var(--line)}.agent-grid{grid-template-columns:1fr}.bubble{max-width:94%}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style>
</head>
<body>
<div class="screen" id="gate"><div class="loader" id="loader"><div class="spin"></div><span>Подключение к XASS…</span></div><div class="login" id="login"><img src="/assets/xass-app-icon-512.png" alt="XASS"><h1>XASS</h1><p>Войдите Telegram-аккаунтом владельца, чтобы управлять системой с iPhone и рабочего стола.</p><div class="widget" id="telegramWidget"></div><button class="btn primary passkey-login" id="passkeyLoginBtn">Войти с Face ID / Passkey</button><div class="ios-help">На iPhone после входа: «Поделиться» → «На экран Домой». XASS откроется как отдельное приложение.</div></div><div class="deny" id="deny"><h2>Нет доступа</h2><p id="denyText">Не удалось подключиться.</p><button class="btn" id="retryBtn">Повторить</button></div></div>
<div class="screen confirm-screen" id="confirmScreen" role="dialog" aria-modal="true" aria-labelledby="confirmTitle"><div class="confirm-card"><h2 id="confirmTitle">Подтвердите действие</h2><p id="confirmText"></p><div class="confirm-actions"><button class="btn" id="confirmCancel">Отмена</button><button class="btn danger" id="confirmYes">Продолжить</button></div></div></div>
<div class="toast" id="toast"></div>
<main class="wrap" id="app" hidden>
 <header class="head"><div class="brand"><img src="/assets/xass-app-icon-192.png" alt=""><span>XASS</span></div><div class="head-state"><span class="dot" id="headDot"></span><span id="headStatus">Подключение</span><span class="head-version" id="headVersion">—</span></div></header>

 <section class="view on" id="view-home">
  <div class="intro"><div class="eyebrow">Личный центр управления</div><h1 id="helloTitle">Система в сети.</h1><p>Сервер, устройства, музыка и сайт — в одном спокойном интерфейсе.</p></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Состояние</h2><span class="section-note" id="appVersion">—</span></div><div class="metrics" id="homeMetrics"></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Устройства</h2><button class="btn" data-view="tools">Управление</button></div><div class="line-list" id="homeDevices"></div></div>
  <div class="section"><a class="home-site" id="homeOpenSite" href="/profile.php" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/></svg><div><div class="row-title">Открыть публичный сайт</div><div class="row-sub">Проверить, как профиль выглядит для посетителей.</div></div><svg class="home-site-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M7 17 17 7M8 7h9v9"/></svg></a></div>
  <div class="section"><div class="pwa-card"><div class="eyebrow">XASS на iPhone</div><div class="row-title" style="font-size:19px;margin-top:8px">Ссылка для домашнего экрана</div><p class="row-sub">Откройте её в Safari, войдите через Telegram и выберите «Поделиться» → «На экран Домой».</p><input class="pwa-url" id="pwaUrl" readonly aria-label="Ссылка XASS для iPhone"><div class="toolbar"><button class="btn primary" id="copyPwaLinkBtn">Копировать ссылку</button><button class="btn" id="sharePwaBtn">Отправить</button></div></div></div>
  <div class="section"><div class="feature feature-grid"><div><div class="eyebrow">Сейчас играет · <span id="homeSource">—</span></div><div class="weather-value" id="homeTrack">Нет свежих данных</div><div class="weather-detail" id="homeTrackHint">Музыкальный поиск доступен в отдельном разделе.</div></div><img class="feature-mark" src="/assets/xass-app-icon-192.png" alt=""></div></div>
 </section>

 <section class="view" id="view-music">
  <div class="intro"><div class="eyebrow">Музыка</div><h1>Трек не должен теряться.</h1><p>Выберите источник, найдите текущую композицию и откройте её в нужном сервисе.</p></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Источник «Сейчас играет»</h2><span class="section-note" id="musicFreshness">LIVE</span></div><div class="seg" id="sourceSeg"><button data-source="pc_agent">ПК</button><button data-source="iphone">iPhone</button><button data-source="vk">VK</button></div><div class="feature"><div class="eyebrow" id="musicSourceLabel">Источник</div><div class="weather-value" id="musicNow">Нет свежих данных</div><div class="weather-detail" id="musicEmptyHint">Источник пока не прислал трек. Поиск ниже всё равно работает.</div></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Найти музыку</h2><span class="section-note">5 сервисов</span></div><div class="search"><input class="input" id="musicInput" placeholder="Исполнитель — трек"><button class="btn primary" id="musicBtn">Найти</button></div><div class="music-result" id="musicResult"><div class="track"><img class="track-art" id="musicArt" alt=""><div><div class="track-title" id="musicTitle"></div><div class="track-meta" id="musicMeta"></div></div></div><div class="links" id="musicLinks"></div></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Подключения</h2></div><div class="line-list"><div class="row"><div class="row-main"><div class="row-title">Discord username</div><div class="row-sub">Нужен для статуса активности на сайте.</div></div></div></div><div class="search"><input class="input" id="discordTag" placeholder="username"><button class="btn" id="discordSave">Сохранить</button></div><div class="field"><label class="label"><span>VK App ID</span><span id="vkState">не подключён</span></label><div class="search"><input class="input" id="vkAppId" inputmode="numeric" placeholder="12345678"><button class="btn" id="vkSave">Сохранить</button></div></div><button class="btn blue" id="vkConnect" style="width:100%;margin-top:9px">Подключить ВКонтакте</button></div>
 </section>

 <section class="view" id="view-tools">
  <div class="intro"><div class="eyebrow">Инструменты</div><h1>Управление без потерь.</h1><p>Настройки бота, Windows-агенты, блокировка экрана и обслуживание сервера.</p></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Бот</h2><span class="section-note">OWNER</span></div><div class="line-list"><div class="row"><div class="row-main"><div class="row-title">Сохранение сообщений</div><div class="row-sub" id="saveModeDesc">—</div></div><button class="btn" id="saveModeBtn">Сменить</button></div><div class="row"><div class="row-main"><div class="row-title">Тихие часы</div><div class="row-sub" id="quietDesc">—</div></div><button class="toggle" id="quietToggle" aria-label="Тихие часы"></button></div><div class="row"><div class="row-main"><div class="row-title">Режим «Не в сети»</div><div class="row-sub" id="awayDesc">—</div></div><button class="toggle" id="awayToggle" aria-label="Режим не в сети"></button></div></div><div class="field"><label class="label"><span>Текст автоответа</span><span id="awayCount">0</span></label><textarea class="input" id="awayMessage" maxlength="4000" placeholder="Напишите полный автоответ…"></textarea><button class="btn blue" id="awaySaveBtn" style="width:100%;margin-top:9px">Сохранить автоответ</button></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">iPhone и веб‑приложение</h2><span class="section-note">ONE TAP</span></div><div class="setup-card"><div class="setup-title">Вход одной ссылкой</div><p class="setup-note">Укажите публичный HTTPS‑адрес XASS. Ссылка действует 10 минут и только один раз: откройте её в Safari, затем добавьте XASS на экран «Домой».</p><div class="field"><label class="label" for="pwaPublicUrl"><span>Публичный адрес сервера</span><span>HTTPS</span></label><input class="input mono" id="pwaPublicUrl" inputmode="url" autocomplete="url" placeholder="https://xass.example"></div><button class="btn primary" id="createIosLinkBtn" style="width:100%;margin-top:10px">Создать ссылку для iPhone</button><div class="pair-link-panel" id="iosPairPanel"><label class="label" for="iosPairLink"><span>Одноразовая ссылка</span><span>Не пересылайте</span></label><input class="pwa-url mono" id="iosPairLink" readonly aria-label="Одноразовая ссылка XASS"><div class="pair-expiry" id="iosPairExpiry"></div><div class="toolbar" style="margin-top:12px"><button class="btn" id="copyIosPairLinkBtn">Копировать</button><button class="btn blue" id="shareIosPairLinkBtn">Открыть / отправить</button></div></div><div class="setup-divider"></div><div class="security-card"><div class="security-icon">◉</div><div class="setup-title">Face ID / Passkey</div><p class="setup-note">После первого входа через Telegram добавьте биометрический ключ. На iPhone используется Face ID или Touch ID, на Windows — Windows Hello.</p><button class="btn primary" id="registerPasskeyBtn" style="width:100%;margin-top:12px">Добавить Face ID / Passkey</button><div class="security-list" id="passkeyList"></div></div><div class="setup-divider"></div><details class="setup-details"><summary>Настройка кнопки Telegram и BotFather</summary><div class="detail-body"><p class="setup-note" id="domainNotice">Это дополнительная настройка кнопки внутри Telegram. На вход iPhone по одноразовой ссылке она не влияет.</p><input class="pwa-url" id="botFatherDomain" readonly aria-label="Домен для BotFather"><div class="readiness" id="domainReadiness"><div class="ready-row" data-ready="bot_username"><span class="ready-icon">·</span><span>Бот определён</span></div><div class="ready-row" data-ready="owner_user_id"><span class="ready-icon">·</span><span>OWNER_USER_ID настроен</span></div><div class="ready-row" data-ready="https"><span class="ready-icon">·</span><span>HTTPS доступен</span></div></div><div class="toolbar"><button class="btn" id="copyDomainBtn">Копировать домен</button><button class="btn blue" id="openBotFatherBtn">Открыть BotFather</button></div><ol class="steps"><li>В @BotFather отправьте <b>/setdomain</b> и выберите бота XASS.</li><li>Отправьте только домен из поля выше — без https:// и пути.</li><li>Кнопка Mini App обновляется автоматически после создания ссылки.</li></ol></div></details></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Windows</h2><span class="section-note">AGENT</span></div><div class="install-row"><img src="/assets/xass-app-icon-192.png" alt=""><div><div class="row-title">XASS для Windows</div><div class="row-sub" id="installerMeta">Проверяю установщик…</div></div></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" id="downloadInstallerBtn">Скачать установщик</button><button class="btn" id="pairBtn">Добавить ПК</button></div><div class="feature" id="pairPanel" style="display:none;margin-top:14px"><div class="eyebrow">Одноразовое подключение</div><div class="pair-code" id="pairCode">—</div><input class="input mono" id="pairServerUrl" placeholder="https://server.example"><div class="row-sub" id="pairExpiry"></div><div class="toolbar" style="margin-top:12px"><button class="btn" id="downloadPairBtn">Файл .xass</button><button class="btn" id="copyPairBtn">Копировать</button></div></div><div class="line-list" id="deviceList" style="margin-top:18px"></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Сервер</h2><button class="btn" id="refreshBtn">Обновить данные</button></div><div class="metrics" id="serverMetrics"></div><div class="line-list" id="serviceList" style="margin-top:18px"></div><div class="toolbar" style="margin-top:14px"><button class="btn" id="checkUpdateBtn">Проверить обновление</button><button class="btn primary" id="runUpdateBtn">Обновить сервер</button><button class="btn danger" id="restartServerBtn">Перезапустить</button></div><pre class="row-sub mono" id="updateResult" style="display:none;white-space:pre-wrap;margin-top:12px"></pre></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Архив переписки</h2><button class="btn" id="conversationsRefresh">Обновить</button></div><div class="archive-summary" id="archiveSummary"></div><div class="archive-note">XASS показывает сообщения, которые получил бот. Удаления доступны для подключённых Telegram Business‑диалогов; обычный Bot API не сообщает об удалении произвольных личных сообщений. Медиа сохраняют выбранные ПК‑агенты, а не VPS.</div><div class="conversation-toolbar"><input class="input" id="conversationSearch" placeholder="Найти диалог"><button class="btn" id="deletedOnlyBtn">Удалённые</button></div><div class="conversation-list" id="conversationList"></div><div class="thread" id="conversationThread"><div class="thread-head"><button class="btn" id="threadBack">← Диалоги</button><span class="section-note" id="threadTitle"></span></div><button class="btn" id="threadMore" style="display:none;width:100%;margin-bottom:10px">Загрузить более ранние</button><div id="threadMessages"></div></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Данные и диагностика</h2></div><div class="disclosure"><details><summary>Последние события</summary><div class="detail-body"><button class="btn" id="logsBtn">Обновить 30</button><div id="logList"></div></div></details><details><summary>Диагностика</summary><div class="detail-body"><p class="muted">Копия безопасной сводки без токенов и ключей.</p><button class="btn" id="copyDiag" style="margin-top:10px">Копировать диагностику</button></div></details></div></div>
 </section>

 <section class="view" id="view-weather">
  <div class="intro"><div class="eyebrow">Погода</div><h1>Живая сводка.</h1><p>Город, температура и условия обновляются автоматически в одном спокойном блоке.</p></div><div class="section"><div class="feature"><div class="eyebrow" id="weatherPlace">Погода</div><div class="weather-value" id="weatherMain">Обновляется…</div><div class="weather-detail" id="weatherDetails"></div></div></div>
 </section>

 <section class="view" id="view-site">
  <div class="intro"><div class="eyebrow">Сайт</div><h1>Профиль без лишнего.</h1><p>Контент, цитаты и проекты собраны в понятный мобильный редактор.</p></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Предпросмотр</h2><button class="btn" id="openSiteBtn">Открыть сайт</button></div><div class="profile-preview"><img id="siteAvatarPreview" src="/assets/xass-app-icon-192.png" alt="Предпросмотр аватара"><div><div class="preview-name" id="sitePreviewName">XASS</div><div class="preview-title" id="sitePreviewTitle">Публичный профиль</div></div><div class="save-state" id="profileSaveState">Сохранено</div></div></div>
  <div class="section"><div class="section-head"><h2 class="section-title">Редактор</h2><span class="section-note">OWNER</span></div><div class="editor-block"><h3 class="editor-title">Основное</h3><div class="form-grid"><div class="field"><label class="label" for="siteName">Имя</label><input class="input" id="siteName" autocomplete="name"></div><div class="field"><label class="label" for="siteUsername">Username</label><input class="input" id="siteUsername" autocomplete="username"></div><div class="field full"><label class="label" for="siteTitle">Заголовок</label><input class="input" id="siteTitle"></div><div class="field full"><label class="label" for="siteBio">О себе</label><textarea class="input" id="siteBio" maxlength="2000"></textarea></div><div class="field full"><label class="label" for="siteTelegram">Telegram URL</label><input class="input" id="siteTelegram" inputmode="url"></div></div><input type="hidden" id="siteQuote"></div>
   <div class="editor-block"><h3 class="editor-title">Аватар</h3><div class="avatar-editor"><img class="avatar-preview" id="siteAvatarEditPreview" src="/assets/xass-app-icon-192.png" alt="Аватар"><div><input class="input" id="siteAvatar" placeholder="URL или загруженный файл"><input type="file" id="siteAvatarFile" accept="image/jpeg,image/png,image/webp" hidden><div class="toolbar" style="margin-top:9px"><button class="btn blue" id="chooseAvatarBtn" type="button">Выбрать из галереи</button><button class="btn" id="clearAvatarBtn" type="button">Убрать</button></div><div class="avatar-helper">JPG, PNG или WebP до 8 МБ. Рекомендуемый размер — квадрат от 512 px.</div></div></div></div>
   <div class="editor-block"><h3 class="editor-title">Ссылки и технологии</h3><details class="editor-detail"><summary class="editor-summary"><span>Технологии</span><span id="stackCount">0</span></summary><div class="field"><label class="label" for="siteStack">Через запятую</label><input class="input" id="siteStack" placeholder="Python, FastAPI, PostgreSQL"></div></details><details class="editor-detail"><summary class="editor-summary"><span>Ссылки</span><span id="linksCount">0</span></summary><div class="field"><label class="label" for="siteLinks">Одна ссылка на строку: Название | URL</label><textarea class="input" id="siteLinks" placeholder="GitHub | https://github.com/…"></textarea></div></details></div>
  </div>
  <div class="section" id="quoteManager"><div class="section-head"><h2 class="section-title">Цитаты</h2><span class="section-note" id="quotesCount">0</span></div><div class="search"><input class="input" id="quoteInput" placeholder="Новая цитата"><button class="btn blue" id="quoteAdd">Добавить</button></div><div class="quote-manager" id="quoteList"></div></div>
