<script>
(()=>{'use strict';
const $=id=>document.getElementById(id), tg=window.Telegram?.WebApp, initData=tg?.initData||'', demo=new URLSearchParams(location.search).get('demo')==='1';
const state={boot:null,site:null,owner:false,pwa:!initData,connection:null,pwaConfig:null,profileDirty:false,iosPairLink:'',conversations:[],activeChat:null,deletedOnly:false,mediaObjectUrls:[],threadBefore:0,threadHasMore:false};
let demoQuotes=[{id:'1',text:'Делаем просто, надежно и без магии.'},{id:'2',text:'Меньше слов — больше дела.'},{id:'3',text:'Хороший код объясняет себя сам.'}];
if(tg){tg.ready();tg.expand();try{tg.setHeaderColor('#000000');tg.setBackgroundColor('#000000')}catch(e){}}
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function copyText(value){const text=String(value||'');if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(text);const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();return Promise.resolve()}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function haptic(kind='light'){try{tg?.HapticFeedback?.impactOccurred(kind)}catch(e){}}
function ask(text,yes){$('confirmText').textContent=text;$('confirmScreen').classList.add('show');const finish=value=>{$('confirmScreen').classList.remove('show');$('confirmYes').onclick=null;$('confirmCancel').onclick=null;yes(!!value)};$('confirmYes').onclick=()=>finish(true);$('confirmCancel').onclick=()=>finish(false)}
function b64bytes(value){const raw=atob(String(value||'').replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((String(value||'').length+3)%4));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function bytesb64(value){const bytes=new Uint8Array(value),raw=Array.from(bytes,b=>String.fromCharCode(b)).join('');return btoa(raw).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function prepareCredentialOptions(options){const o=structuredClone(options);o.challenge=b64bytes(o.challenge);if(o.user?.id)o.user.id=b64bytes(o.user.id);for(const item of o.excludeCredentials||[])item.id=b64bytes(item.id);for(const item of o.allowCredentials||[])item.id=b64bytes(item.id);return o}
function serializeCredential(credential){const response={clientDataJSON:bytesb64(credential.response.clientDataJSON)};if(credential.response.attestationObject)response.attestationObject=bytesb64(credential.response.attestationObject);if(credential.response.authenticatorData)response.authenticatorData=bytesb64(credential.response.authenticatorData);if(credential.response.signature)response.signature=bytesb64(credential.response.signature);if(credential.response.userHandle)response.userHandle=bytesb64(credential.response.userHandle);if(credential.response.getTransports)response.transports=credential.response.getTransports();return{id:credential.id,rawId:bytesb64(credential.rawId),type:credential.type,response,clientExtensionResults:credential.getClientExtensionResults(),authenticatorAttachment:credential.authenticatorAttachment||null}}
async function passkeyAuthenticate(purpose='login'){if(!window.PublicKeyCredential)throw new Error('Это устройство не поддерживает Passkey');const start=await pwaApi('passkeys/login/options',{method:'POST',body:{purpose}});if(start.status!==200||!start.data?.ok)throw new Error(start.data?.detail||'Не удалось начать проверку');const credential=await navigator.credentials.get({publicKey:prepareCredentialOptions(start.data.options)});const done=await pwaApi('passkeys/login/verify',{method:'POST',body:{transaction:start.data.transaction,credential:serializeCredential(credential)}});if(done.status!==200||!done.data?.ok)throw new Error(done.data?.detail||'Passkey отклонён');return done.data}
async function passkeyAction(purpose){if(!state.pwa||!(state.boot?.passkeys||[]).length)return'';const result=await passkeyAuthenticate(purpose);return result.action_proof||''}
function demoBoot(){return{ok:true,app_version:'0.10.0',user:{id:42,first_name:'Владелец',is_owner:true},metrics:{cpu_percent:18,ram_used_percent:43,disk_used_percent:61},status:{now_listening:'M83 — Midnight City',now_source:'pc_agent',now_source_label:'PC',weather:'Москва: 24.1°C, малооблачно, ощущается как 25.2°C, ветер 2.7 м/с',discord_tag:'owner',vk_connected:false},settings:{save_mode:'SAVE_FULL',quiet_enabled:true,away_enabled:false,away_message:'Привет, я сейчас не в сети. Сообщение сохранено — отвечу, как смогу.',service_base_url:location.origin},sources:[{source_name:'Домашний ПК',source_type:'PC_AGENT',is_online:true,last_seen_at:new Date().toISOString(),agent_version:'0.9.0',archive_enabled:true,last_payload:{platform:'Windows',metrics:{cpu_percent:21,ram_used_percent:46,disk_used_percent:57,net_rx_mb:1824,net_tx_mb:640},active_app:'XASS',archive_status:{cursor:126}}},{source_name:'Рабочий ноутбук',source_type:'PC_AGENT',is_online:true,last_seen_at:new Date(Date.now()-42000).toISOString(),agent_version:'0.9.0',archive_enabled:false,last_payload:{platform:'Windows',metrics:{cpu_percent:12,ram_used_percent:39,disk_used_percent:44}}},{source_name:'iPhone',source_type:'IPHONE',is_online:false,last_seen_at:new Date(Date.now()-3600000).toISOString(),agent_version:'1.0.0',last_payload:{platform:'iOS'}}],services:{nginx:'active',postgresql:'active'},windows_installer:{available:true,version:'0.9.0',size:21502586,file_name:'XASS-Setup.exe',fallback_url:'https://github.com/lucifervalter-a11y/XASS/releases/download/agent-latest/XASS-Setup.exe'},archive:{messages:128,deleted:7,media:19,targets:1},passkeys:[],vk_app_id:''}}
function demoApi(path,opts={}){let data={ok:true};if(path==='bootstrap')data=demoBoot();else if(path.startsWith('music'))data={ok:true,artist:'M83',title:'Midnight City',album:'Hurry Up, We’re Dreaming',artwork_url:'',links:{VK:'#',Shazam:'#','Apple Music':'#',Google:'#','Yandex Music':'#'}};else if(path==='site')data={ok:true,can_edit:true,public_url:'/profile.php',profile:{name:'XASS',username:'lucifervalter',title:'Системы, которые остаются живыми.',bio:'Собираю ботов, сервисы и интерфейсы — от идеи до работающего продакшена.',telegram_url:'https://t.me/lucifervalter',avatar_url:'',quote:demoQuotes[0].text,stack:['Python','FastAPI','PostgreSQL'],links:[{label:'GitHub',url:'https://github.com/lucifervalter-a11y'},{label:'Steam',url:'https://steamcommunity.com/'}]},projects:[{id:'xass',title:'XASS',status:'live',description:'Личный центр управления.',years:{from:2025,to:2026},tags:['Python'],cover:{src:''}},{id:'portfolio',title:'Portfolio',status:'live',description:'Публичная визитка.',years:{from:2026,to:2026},tags:['PHP'],cover:{src:''}}]};else if(path==='conversations')data={ok:true,archive:{messages:128,deleted:7,media:19,targets:1},chats:[{chat_id:42,title:'Алексей',count:84,deleted:6,last_text:'Сообщение было удалено'},{chat_id:73,title:'Рабочий чат',count:44,deleted:1,last_text:'Финальная версия готова'}]};else if(path.startsWith('conversations/'))data={ok:true,has_more:false,messages:[{id:1,direction:'incoming',date:new Date(Date.now()-60000).toISOString(),from_username:'alex',text:'Привет, проверь архив',deleted:false,edited:false,media:[],revisions:[{event:'create',text:'Привет, проверь архив',date:new Date(Date.now()-60000).toISOString()}]},{id:2,direction:'incoming',date:new Date().toISOString(),from_username:'alex',text:'Это сообщение удалили, но XASS его сохранил.',deleted:true,edited:true,media:[],revisions:[{event:'create',text:'Черновик',date:new Date(Date.now()-30000).toISOString()},{event:'edit',text:'Это сообщение удалили, но XASS его сохранил.',date:new Date(Date.now()-15000).toISOString()},{event:'delete',text:'Это сообщение удалили, но XASS его сохранил.',date:new Date().toISOString()}]}]};else if(path.startsWith('logs'))data={ok:true,logs:[{chat_title:'XASS',direction:'system',text:'Heartbeat получен',date:new Date().toISOString()}]};else if(path==='quotes'&&(!opts.method||opts.method==='GET'))data={ok:true,quotes:demoQuotes};else if(path==='quotes'&&opts.method==='POST'){demoQuotes.push({id:String(Date.now()),text:opts.body?.text||''});data={ok:true,quotes:demoQuotes}}else if(path.startsWith('quotes/')&&opts.method==='DELETE'){demoQuotes=demoQuotes.filter(x=>x.id!==decodeURIComponent(path.split('/')[1]));data={ok:true,quotes:demoQuotes}}else if(path.startsWith('quotes/')&&opts.method==='PUT'){const id=decodeURIComponent(path.split('/')[1]),item=demoQuotes.find(x=>x.id===id);if(item)item.text=opts.body?.text||item.text;data={ok:true,quotes:demoQuotes}}else if(path==='agents/pair-code')data={ok:true,code:'XASS2048',ttl_minutes:15,server_url:location.origin,connection:{format:'xass-connect',version:1,server_url:location.origin,pair_code:'XASS2048',auto_update:true}};else if(path==='pwa/pair-link')data={ok:true,public_url:location.origin,link:location.origin+'/miniapp.php?standalone=1#pair=xpw_demo',ttl_minutes:10,menu_update_scheduled:true};else if(path==='update-status')data={ok:true,has_updates:true,commits:[{subject:'UI and PWA'}]};else if(path==='run-update'||path==='restart')data={ok:true,restart_scheduled:false,steps:['Готово']};else if(path.includes('/commands'))data={ok:true,command:{status:'pending'}};else if(path==='setting')data={ok:true,settings:state.boot.settings,status:state.boot.status};else if(path==='vk-url')data={ok:true,url:'#'};return Promise.resolve({status:200,data})}
function api(path,opts={}){if(demo)return demoApi(path,opts);const headers=new Headers(opts.headers||{});if(initData)headers.set('X-Telegram-Init-Data',initData);if(opts.body&&typeof opts.body!=='string'){headers.set('Content-Type','application/json');opts.body=JSON.stringify(opts.body)}return fetch('/proxy.php?_p='+encodeURIComponent('/api/mini/'+path),{...opts,headers,credentials:'include'}).then(async r=>{const env=await r.json();let data=null;try{data=JSON.parse(env._b||'')}catch(e){}return{status:Number(env._s||r.status),data,raw:env._b||''}})}
async function pwaApi(path,opts={}){if(demo&&path==='config')return{status:200,data:{ok:true,authenticated:false,bot_username:'xass_bot',login_ready:true,domain:location.hostname,domain_verification:'telegram_only',requirements:{bot_token:true,bot_username:true,owner_user_id:true,https:true}}};const headers=new Headers(opts.headers||{});if(initData)headers.set('X-Telegram-Init-Data',initData);if(opts.body&&typeof opts.body!=='string'){headers.set('Content-Type','application/json');opts.body=JSON.stringify(opts.body)}const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/pwa/'+path),{...opts,headers,credentials:'include'});let data=null;try{data=await response.json()}catch(e){}return{status:Number(response.headers.get('X-XASS-Status')||response.status),data}}
function metricHtml(m={}){return[['CPU',m.cpu_percent],['Память',m.ram_used_percent],['Диск',m.disk_used_percent]].map(([name,v])=>{v=Math.max(0,Math.min(100,Number(v)||0));return'<div class="metric"><div class="metric-name">'+name+'</div><div class="metric-value">'+Math.round(v)+'%</div><div class="metric-bar"><i style="width:'+v+'%"></i></div></div>'}).join('')}
function age(iso){if(!iso)return'нет данных';const sec=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);return sec<60?Math.round(sec)+' сек назад':sec<3600?Math.floor(sec/60)+' мин назад':Math.floor(sec/3600)+' ч назад'}
function versionAtLeast(value,wanted){const a=String(value||'0').split('.').map(Number),b=wanted.split('.').map(Number);for(let i=0;i<3;i++){if((a[i]||0)>(b[i]||0))return true;if((a[i]||0)<(b[i]||0))return false}return true}
function isPc(item){return /pc|windows/i.test(String(item.source_type||'')+' '+String(item.last_payload?.platform||''))}
function valueText(value,suffix=''){const n=Number(value);return Number.isFinite(n)?Math.round(n*10)/10+suffix:'—'}
function deviceHtml(list,actions=false){return(list||[]).map(item=>{const pc=isPc(item),old=pc&&!versionAtLeast(item.agent_version,'0.6.0'),p=item.last_payload||{},m=p.metrics||{},a=p.archive_status||{};return'<div class="row"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">'+(pc?'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>':'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/>')+'</svg><div class="row-main"><div class="row-title">'+esc(item.source_name)+'</div><div class="row-sub">v'+esc(item.agent_version||'0.0.0')+' · '+age(item.last_seen_at)+'</div>'+(old?'<div class="warning">Для блокировки установите свежий агент.</div>':'')+(actions&&state.owner?'<div class="device-actions"><button class="btn blue agent-command" data-source="'+esc(item.source_name)+'" data-command="update">Обновить</button><button class="btn agent-command" data-source="'+esc(item.source_name)+'" data-command="restart">Перезапустить</button>'+(pc?'<button class="btn danger agent-command" data-source="'+esc(item.source_name)+'" data-command="lock">Заблокировать экран</button><button class="btn archive-toggle" data-source="'+esc(item.source_name)+'" data-enabled="'+(!item.archive_enabled)+'">'+(item.archive_enabled?'Не хранить архив':'Хранить архив здесь')+'</button>':'')+'</div>':'')+(actions?'<details class="agent-details"><summary>Статистика агента</summary><div class="agent-grid"><div class="agent-stat"><span>CPU</span><b>'+valueText(m.cpu_percent,'%')+'</b></div><div class="agent-stat"><span>Память</span><b>'+valueText(m.ram_used_percent,'%')+' · '+valueText(m.ram_used_mb,' МБ')+'</b></div><div class="agent-stat"><span>Диск</span><b>'+valueText(m.disk_used_percent,'%')+' · '+valueText(m.disk_used_gb,' ГБ')+'</b></div><div class="agent-stat"><span>Сеть</span><b>↓ '+valueText(m.net_rx_mb,' МБ')+' · ↑ '+valueText(m.net_tx_mb,' МБ')+'</b></div><div class="agent-stat"><span>Активность</span><b>'+esc(p.active_app||'нет данных')+'</b></div><div class="agent-stat"><span>Локальный архив</span><b>'+(item.archive_enabled?'включён · '+valueText(a.cursor,' событий'):'выключен')+'</b></div></div></details>':'')+'</div><span class="status '+(item.is_online?'':'off')+'">'+(item.is_online?'В сети':'Offline')+'</span></div>'}).join('')||'<div class="empty">Устройства ещё не подключены.</div>'}
function renderSettings(s={}){const modes={SAVE_OFF:'Выключено',SAVE_BASIC:'Базовый',SAVE_FULL:'Полный + медиа',SAVE_PRIVATE_ONLY:'Только личные',SAVE_GROUPS_ONLY:'Только группы'};$('saveModeDesc').textContent=modes[s.save_mode]||s.save_mode||'—';$('quietToggle').classList.toggle('on',!!s.quiet_enabled);$('quietDesc').textContent=s.quiet_enabled?'Включены':'Выключены';$('awayToggle').classList.toggle('on',!!s.away_enabled);$('awayDesc').textContent=s.away_enabled?'Автоответ включён':'Выключен';$('awayMessage').value=s.away_message||'';if(!$('pwaPublicUrl').value)$('pwaPublicUrl').value=s.service_base_url||location.origin;updateAwayCount()}
function renderMusic(status={}){const source=status.now_source||'pc_agent',raw=String(status.now_listening||'').trim(),stale=!raw||/нет (свежих )?данных|ничего не играет/i.test(raw);document.querySelectorAll('#sourceSeg button').forEach(b=>b.classList.toggle('on',b.dataset.source===source));$('homeSource').textContent=status.now_source_label||source;$('musicSourceLabel').textContent='Источник · '+(status.now_source_label||source);$('homeTrack').textContent=stale?'Нет свежих данных':raw;$('musicNow').textContent=stale?'Нет свежих данных':raw;$('homeTrackHint').textContent=stale?'Выберите ПК, iPhone или VK — поиск музыки всё равно доступен.':'Нажмите раздел «Музыка», чтобы открыть трек в сервисах.';$('musicEmptyHint').textContent=stale?'Источник пока не прислал трек. Введите название ниже или переключите источник.':'Можно найти этот трек во всех сервисах ниже.';$('musicInput').value=stale?'':raw;$('discordTag').value=status.discord_tag||'';$('vkState').textContent=status.vk_connected?'подключён':'не подключён'}
function renderWeather(text=''){const parts=String(text||'').split(',').map(x=>x.trim()).filter(Boolean),first=parts.shift()||'Погода обновляется…';let place='Погода',main=first;if(first.includes(':')){const cut=first.indexOf(':');place='Погода · '+first.slice(0,cut);main=first.slice(cut+1).trim()}$('weatherPlace').textContent=place;$('weatherMain').textContent=main;$('weatherDetails').textContent=parts.join(' · ')||'Свежая сводка появится после обновления сервера.'}
function renderInstaller(info={}){const ready=!!(info.available||info.fallback_url);$('downloadInstallerBtn').disabled=!ready;$('installerMeta').textContent=info.available?'Версия '+(info.version||'—')+' · '+(info.size?Math.max(1,Math.round(info.size/1048576))+' МБ':'готов к загрузке'):info.fallback_url?'Стабильный установщик доступен через GitHub':'Установщик ещё собирается'}
function bindCommands(){document.querySelectorAll('.agent-command').forEach(btn=>btn.onclick=()=>{const run=async()=>{btn.disabled=true;try{const purpose='agent:'+btn.dataset.command+':'+btn.dataset.source,proof=await passkeyAction(purpose),r=await api('agents/'+encodeURIComponent(btn.dataset.source)+'/commands',{method:'POST',body:{command:btn.dataset.command,payload:{},action_proof:proof}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось отправить команду');toast(btn.dataset.command==='lock'?'Команда Win + L отправлена':'Команда отправлена')}catch(e){toast(e.message||'Нет связи')}finally{btn.disabled=false}};['lock','restart'].includes(btn.dataset.command)?ask((btn.dataset.command==='lock'?'Заблокировать экран ':'Перезапустить агент ')+btn.dataset.source+'?',ok=>ok&&run()):run()});document.querySelectorAll('.archive-toggle').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const enabled=btn.dataset.enabled==='true',r=await api('agents/'+encodeURIComponent(btn.dataset.source)+'/archive',{method:'POST',body:{enabled}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось изменить хранилище');toast(enabled?'Агент выбран для локального архива':'Локальный архив на агенте выключен');await loadBoot()}catch(e){toast(e.message)}finally{btn.disabled=false}})}
function renderDomainReadiness(config={}){state.pwaConfig=config;const req=config.requirements||{bot_token:true,bot_username:!!config.bot_username,owner_user_id:true,https:location.protocol==='https:'},domain=config.domain||location.hostname;$('botFatherDomain').value=domain;document.querySelectorAll('[data-ready]').forEach(row=>{const ok=!!req[row.dataset.ready];row.classList.toggle('ok',ok);row.classList.toggle('bad',!ok);row.querySelector('.ready-icon').textContent=ok?'✓':'!'});const missing=Object.entries(req).filter(([,ok])=>!ok).map(([key])=>({bot_token:'BOT_TOKEN',bot_username:'имя бота',owner_user_id:'OWNER_USER_ID',https:'HTTPS'}[key]||key));$('domainNotice').textContent=missing.length?'Локально не готово: '+missing.join(', ')+'. Это не означает, что /setdomain не сохранён.':'Локальная часть XASS готова. Если Telegram ещё показывает ошибку, повторите /setdomain для того же бота и отправьте ровно «'+domain+'».'}
async function loadPwaReadiness(){try{const r=await pwaApi('config');if(r.data?.ok)renderDomainReadiness(r.data);else renderDomainReadiness({})}catch(e){renderDomainReadiness({})}}
function renderPasskeys(list=[]){$('passkeyList').innerHTML=list.map(x=>'<div class="security-item"><span>'+esc(x.name||'Passkey')+'</span><span class="muted">'+(x.last_used_at?'использован '+age(x.last_used_at):'добавлен')+'</span></div>').join('')||'<div class="empty">Passkey ещё не добавлен.</div>'}
function renderArchiveSummary(a={}){$('archiveSummary').innerHTML=[['Сообщения',a.messages||0],['Удалено',a.deleted||0],['Медиа',a.media||0],['ПК-хранилища',a.targets||0]].map(([name,value])=>'<div class="archive-number"><b>'+esc(value)+'</b><span>'+name+'</span></div>').join('')}
function renderBoot(data){state.boot=data;state.owner=!!data.user?.is_owner;const version=data.app_version||'';$('appVersion').textContent='XASS '+version;$('headVersion').textContent=version||'—';$('headStatus').textContent='В сети';$('headDot').className='dot ok';$('helloTitle').textContent=(data.user?.first_name?'Привет, '+data.user.first_name+'.':'Система в сети.');$('homeMetrics').innerHTML=metricHtml(data.metrics);$('serverMetrics').innerHTML=metricHtml(data.metrics);$('homeDevices').innerHTML=deviceHtml((data.sources||[]).slice(0,3));$('homeDevices').classList.add('soft');$('deviceList').innerHTML=deviceHtml(data.sources||[],true);bindCommands();renderSettings(data.settings);renderMusic(data.status);renderWeather(data.status?.weather);renderInstaller(data.windows_installer||{});renderPasskeys(data.passkeys||[]);renderArchiveSummary(data.archive||{});$('vkAppId').value=data.vk_app_id||'';$('pwaUrl').value=state.iosPairLink||'Создайте одноразовую ссылку для iPhone';$('botFatherDomain').value=location.hostname;$('homeOpenSite').href=location.origin+'/profile.php';$('serviceList').innerHTML=Object.entries(data.services||{}).map(([name,value])=>'<div class="row"><div class="row-main"><div class="row-title">'+esc(name)+'</div></div><span class="status '+(value==='active'?'':'off')+'">'+esc(value)+'</span></div>').join('')||'<div class="empty">Сервисы не настроены.</div>';$('gate').style.display='none';$('app').hidden=false;$('tabs').hidden=false;$('logoutBtn').style.display=state.pwa?'inline-block':'none';loadPwaReadiness();loadConversations()}
function loadBoot(){return api('bootstrap').then(r=>{if(r.status!==200||!r.data?.ok)throw new Error(r.data?.detail||'Нет доступа');renderBoot(r.data)}).catch(error=>showDeny(error.message))}
function showDeny(text){$('loader').style.display='none';$('login').style.display='none';$('deny').style.display='block';$('denyText').textContent=text||'Не удалось подключиться.'}
function showView(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('on',v.id==='view-'+name));document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.view===name));scrollTo({top:0,behavior:'smooth'});if(name==='site'&&!state.site)loadSite();if(name==='tools')loadUpdateStatus()}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{const leavingSite=document.getElementById('view-site').classList.contains('on')&&button.dataset.view!=='site'&&state.profileDirty;if(leavingSite)return ask('Есть несохранённые изменения профиля. Перейти без сохранения?',ok=>ok&&showView(button.dataset.view));showView(button.dataset.view)});$('retryBtn').onclick=()=>location.reload();$('refreshBtn').onclick=loadBoot;
function showIosPairLink(data={}){state.iosPairLink=data.link||'';if(data.public_url){$('pwaPublicUrl').value=data.public_url;if(state.boot?.settings)state.boot.settings.service_base_url=data.public_url}$('iosPairLink').value=state.iosPairLink;$('pwaUrl').value=state.iosPairLink||'Создайте одноразовую ссылку для iPhone';$('iosPairExpiry').textContent=state.iosPairLink?'Ссылка действует '+(data.ttl_minutes||10)+' минут и сработает один раз.':'';$('iosPairPanel').classList.toggle('show',!!state.iosPairLink)}
async function createIosPairLink(){const button=$('createIosLinkBtn'),publicUrl=$('pwaPublicUrl').value.trim();if(!publicUrl)return toast('Укажите публичный HTTPS‑адрес XASS');button.disabled=true;button.textContent='Создаю защищённую ссылку…';try{const r=await api('pwa/pair-link',{method:'POST',body:{public_url:publicUrl}});if(r.status!==200||!r.data?.ok)throw new Error(r.data?.detail||'Не удалось создать ссылку');showIosPairLink(r.data);toast(r.data.menu_update_scheduled?'Ссылка готова · кнопка бота обновится в фоне':'Ссылка для iPhone готова');haptic('medium');return r.data.link}catch(e){toast(e.message||'Не удалось создать ссылку');return''}finally{button.disabled=false;button.textContent='Создать новую ссылку для iPhone'}}
$('createIosLinkBtn').onclick=createIosPairLink;
