$('shareIosPairLinkBtn').onclick=async()=>{const url=state.iosPairLink;if(!url)return;if(tg?.openLink){tg.openLink(url);return}if(navigator.share){try{await navigator.share({title:'XASS',text:'Одноразовый вход XASS на iPhone',url});return}catch(e){if(e?.name==='AbortError')return}}window.open(url,'_blank','noopener')};
