$('sharePwaBtn').onclick=async()=>{const url=state.iosPairLink||await createIosPairLink();if(!url)return;if(navigator.share){try{await navigator.share({title:'XASS',text:'Открыть XASS и добавить на экран Домой',url});return}catch(e){if(e?.name==='AbortError')return}}if(tg?.openLink)tg.openLink(url);else window.open(url,'_blank','noopener')};
$('homeOpenSite').onclick=event=>{if(!tg?.openLink)return;event.preventDefault();tg.openLink($('homeOpenSite').href)};
$('copyDomainBtn').onclick=()=>copyText(location.hostname).then(()=>toast('Домен скопирован'));
$('openBotFatherBtn').onclick=()=>{const url='https://t.me/BotFather';if(tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank')};
function pushSetting(key,value,done){api('setting',{method:'POST',body:{key,value}}).then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Ошибка');if(r.data.settings){state.boot.settings=r.data.settings;renderSettings(r.data.settings)}if(r.data.status){state.boot.status=r.data.status;renderMusic(r.data.status)}done?.()})}
$('saveModeBtn').onclick=()=>pushSetting('save_mode_cycle',null);$('quietToggle').onclick=()=>pushSetting('quiet_toggle',null);$('awayToggle').onclick=()=>pushSetting('away_toggle',null);$('awaySaveBtn').onclick=()=>pushSetting('away_message',$('awayMessage').value,()=>toast('Автоответ сохранён'));function updateAwayCount(){$('awayCount').textContent=$('awayMessage').value.length+' / 4000'}$('awayMessage').addEventListener('input',updateAwayCount);
document.querySelectorAll('#sourceSeg button').forEach(button=>button.onclick=()=>pushSetting('now_source',button.dataset.source,()=>{renderMusic({...state.boot.status,now_source:button.dataset.source,now_source_label:button.textContent});toast('Источник изменён')}));
async function findMusic(){const q=$('musicInput').value.trim();if(!q)return toast('Введите исполнителя и трек');$('musicBtn').disabled=true;$('musicBtn').textContent='Ищу…';try{const r=await api('music?q='+encodeURIComponent(q));if(!r.data?.ok)throw new Error(r.data?.detail||'Не найдено');const d=r.data;$('musicResult').style.display='block';$('musicTitle').textContent=[d.artist,d.title].filter(Boolean).join(' — ')||d.query;$('musicMeta').textContent=d.album||'Альбом не указан';$('musicArt').src=d.artwork_url||'/assets/xass-app-icon-192.png';$('musicLinks').innerHTML=Object.entries(d.links||{}).map(([label,url])=>'<a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc(label)+' ↗</a>').join('');haptic('medium')}catch(e){toast(e.message)}finally{$('musicBtn').disabled=false;$('musicBtn').textContent='Найти'}}$('musicBtn').onclick=findMusic;$('musicInput').addEventListener('keydown',e=>{if(e.key==='Enter')findMusic()});
$('discordSave').onclick=()=>pushSetting('discord_tag',$('discordTag').value,()=>toast('Discord сохранён'));$('vkSave').onclick=()=>pushSetting('vk_app_id',$('vkAppId').value,()=>toast('VK App ID сохранён'));$('vkConnect').onclick=()=>api('vk-url?chat_id='+(state.boot?.user?.id||'')).then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Сначала сохраните VK App ID');const url=r.data.url;if(tg?.openLink)tg.openLink(url);else window.open(url,'_blank')});
$('pairBtn').onclick=function(){this.disabled=true;api('agents/pair-code',{method:'POST',body:{server_url:location.origin}}).then(r=>{this.disabled=false;if(!r.data?.ok)return toast(r.data?.detail||'Ошибка');state.connection=r.data.connection;$('pairPanel').style.display='block';$('pairCode').textContent=r.data.code;$('pairServerUrl').value=r.data.server_url||location.origin;$('pairExpiry').textContent='Ключ действует '+r.data.ttl_minutes+' мин'})};function connection(){return state.connection?{...state.connection,server_url:$('pairServerUrl').value.trim(),pair_code:$('pairCode').textContent.trim()}:null}$('downloadPairBtn').onclick=()=>{const p=connection();if(!p)return;const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='xass-connect.xass';a.click();setTimeout(()=>URL.revokeObjectURL(url),700)};$('copyPairBtn').onclick=()=>{const p=connection();if(!p)return;navigator.clipboard?.writeText('Сервер: '+p.server_url+'\nКлюч: '+p.pair_code);toast('Скопировано')};
$('downloadInstallerBtn').onclick=async function(){if(demo)return toast('Демо: загрузка XASS-Setup.exe');this.disabled=true;const fallback=state.boot?.windows_installer?.fallback_url||'';try{const result=await api('agent-installer/ticket');if(!result.data?.ok)throw new Error(result.data?.detail||'Локальный установщик недоступен');const streamUrl='/proxy.php?_binary=1&_p='+encodeURIComponent(result.data.download_path),a=document.createElement('a');a.href=streamUrl;a.download=state.boot?.windows_installer?.file_name||'XASS-Setup.exe';document.body.appendChild(a);a.click();a.remove();toast('Загрузка установщика началась')}catch(e){if(fallback){if(tg?.openLink)tg.openLink(fallback);else window.open(fallback,'_blank');toast('Открываю резервную загрузку GitHub')}else toast(e.message||'Не удалось скачать установщик')}finally{setTimeout(()=>renderInstaller(state.boot.windows_installer||{}),700)}};
function loadUpdateStatus(){api('update-status').then(r=>{const d=r.data||{};$('updateResult').style.display='block';$('updateResult').textContent=d.has_updates?'Доступно изменений: '+(d.commits||[]).length:'Сервер обновлён';$('runUpdateBtn').disabled=!d.has_updates})}$('checkUpdateBtn').onclick=loadUpdateStatus;$('runUpdateBtn').onclick=function(){this.disabled=true;$('updateResult').style.display='block';$('updateResult').textContent='Устанавливаю обновление…';api('run-update',{method:'POST'}).then(r=>{$('updateResult').textContent=r.data?.ok?'Готово\n'+(r.data.steps||[]).join('\n'):'Ошибка: '+(r.data?.error||r.data?.detail||'нет данных');this.disabled=false}).catch(()=>{$('updateResult').textContent='Связь прервана — сервер перезапускается.';this.disabled=false})};$('restartServerBtn').onclick=()=>ask('Перезапустить backend XASS?',ok=>{if(ok)api('restart',{method:'POST'}).then(()=>toast('Перезапуск запланирован'))});
function loadLogs(){api('logs?limit=30').then(r=>{$('logList').innerHTML=(r.data?.logs||[]).map(x=>'<div class="log"><div class="log-meta"><span>'+esc(x.chat_title||x.from_username||'XASS')+' · '+esc(x.direction||'')+'</span><span>'+(x.date?new Date(x.date).toLocaleString('ru-RU'):'')+'</span></div><div class="log-text">'+esc(x.text||'')+'</div></div>').join('')||'<div class="empty">Сообщений нет.</div>'})}$('logsBtn').onclick=loadLogs;
function filterConversations(){const q=$('conversationSearch').value.trim().toLowerCase(),rows=state.conversations.filter(x=>(!q||String(x.title+' '+x.last_text).toLowerCase().includes(q))&&(!state.deletedOnly||Number(x.deleted)>0));$('conversationList').innerHTML=rows.map(x=>'<button class="chat-row" data-chat="'+x.chat_id+'"><span><span class="chat-title">'+esc(x.title)+'</span><span class="chat-preview">'+esc(x.last_text||'Нет текста')+'</span></span><span><span class="section-note">'+esc(x.count)+'</span>'+(x.deleted?'<span class="chat-badge"> · удалено '+esc(x.deleted)+'</span>':'')+'</span></button>').join('')||'<div class="empty">Диалоги не найдены.</div>';document.querySelectorAll('.chat-row').forEach(row=>row.onclick=()=>openConversation(Number(row.dataset.chat)))}
async function loadConversations(){try{const r=await api('conversations');if(!r.data?.ok)return;state.conversations=r.data.chats||[];renderArchiveSummary(r.data.archive||{});filterConversations()}catch(e){}}
async function loadThreadMedia(node){if(node.dataset.loaded||node.dataset.loading)return;node.dataset.loading='1';node.textContent='Загружаю медиа…';try{const headers={};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_binary=1&_p='+encodeURIComponent('/api/mini/media/'+node.dataset.mediaId),{headers,credentials:'include'});if(!response.ok||Number(response.headers.get('X-XASS-Status')||response.status)>=400)throw new Error('media');const blob=await response.blob(),url=URL.createObjectURL(blob),mime=node.dataset.mime||blob.type||'';state.mediaObjectUrls.push(url);node.dataset.loaded='1';if(mime.startsWith('image/'))node.innerHTML='<img class="media-preview" alt="Медиа сообщения">';else if(mime.startsWith('video/'))node.innerHTML='<video class="media-preview" controls preload="metadata"></video>';else if(mime.startsWith('audio/'))node.innerHTML='<audio class="media-preview" controls preload="metadata"></audio>';else node.innerHTML='<a class="media-download" download>Скачать файл</a>';node.firstElementChild.src=url}catch(e){node.textContent='Медиа уже недоступно в Telegram; локальная копия остаётся на выбранных ПК.'}finally{delete node.dataset.loading}}
function bindThreadMedia(reset=false){if(reset){state.mediaObjectUrls.forEach(URL.revokeObjectURL);state.mediaObjectUrls=[]}document.querySelectorAll('[data-media-id]:not([data-loaded])').forEach(node=>node.onclick=()=>loadThreadMedia(node))}
function messageBubble(m){return'<div class="bubble '+(m.direction==='outgoing'?'out ':'')+(m.deleted?'deleted':'')+'"><div class="bubble-meta">'+(m.date?new Date(m.date).toLocaleString('ru-RU'):'')+(m.from_username?' · @'+esc(m.from_username):'')+(m.deleted?' · <span class="deleted-pill">удалено</span>':'')+(m.edited?' · изменено':'')+'</div><div class="bubble-text">'+esc(m.text||'Медиа / сообщение без текста')+'</div>'+(m.media?.length?'<div class="bubble-media">Файлов: '+m.media.length+' · постоянные копии находятся на выбранных ПК‑агентах</div><div class="bubble-media-files">'+m.media.map(file=>'<button class="media-download" type="button" data-media-id="'+esc(file.id)+'" data-mime="'+esc(file.mime_type||'')+'">Открыть '+esc(file.type||'медиа')+'</button>').join('')+'</div>':'')+(m.revisions?.length>1?'<details class="agent-details"><summary>История изменений</summary>'+m.revisions.map(x=>'<div class="log"><div class="log-meta">'+esc(x.event)+' · '+new Date(x.date).toLocaleString('ru-RU')+'</div><div class="log-text">'+esc(x.text||'—')+'</div></div>').join('')+'</details>':'')+'</div>'}
async function openConversation(chatId,before=0){const prepend=before>0,r=await api('conversations/'+encodeURIComponent(chatId)+'?limit=150&before='+before+'&deleted_only='+(state.deletedOnly?'true':'false'));if(!r.data?.ok)return toast(r.data?.detail||'Не удалось открыть переписку');state.activeChat=chatId;const chat=state.conversations.find(x=>Number(x.chat_id)===chatId),messages=r.data.messages||[],html=messages.map(messageBubble).join('');$('threadTitle').textContent=chat?.title||String(chatId);$('conversationList').style.display='none';$('conversationThread').classList.add('show');if(prepend)$('threadMessages').insertAdjacentHTML('afterbegin',html);else $('threadMessages').innerHTML=html||'<div class="empty">Сообщений здесь пока нет.</div>';state.threadBefore=messages[0]?.id||state.threadBefore||0;state.threadHasMore=!!r.data.has_more&&!!messages.length;$('threadMore').style.display=state.threadHasMore?'block':'none';bindThreadMedia(!prepend)}
$('threadMore').onclick=()=>state.activeChat&&state.threadBefore&&openConversation(state.activeChat,state.threadBefore);$('threadBack').onclick=()=>{$('conversationThread').classList.remove('show');$('conversationList').style.display='block';state.mediaObjectUrls.forEach(URL.revokeObjectURL);state.mediaObjectUrls=[];state.activeChat=null;state.threadBefore=0};$('conversationSearch').addEventListener('input',filterConversations);$('conversationsRefresh').onclick=loadConversations;$('deletedOnlyBtn').onclick=()=>{state.deletedOnly=!state.deletedOnly;$('deletedOnlyBtn').classList.toggle('blue',state.deletedOnly);$('deletedOnlyBtn').textContent=state.deletedOnly?'Показаны удалённые':'Удалённые';state.activeChat?openConversation(state.activeChat):filterConversations()};
async function registerPasskey(){if(!window.PublicKeyCredential)return toast('Браузер не поддерживает Passkey');const button=$('registerPasskeyBtn');button.disabled=true;try{const start=await pwaApi('passkeys/register/options',{method:'POST'});if(start.status!==200||!start.data?.ok)throw new Error(start.data?.detail||'Не удалось начать регистрацию');const credential=await navigator.credentials.create({publicKey:prepareCredentialOptions(start.data.options)}),name=/iPhone|iPad/i.test(navigator.userAgent)?'Face ID на iPhone':/Windows/i.test(navigator.userAgent)?'Windows Hello':'Passkey устройства',done=await pwaApi('passkeys/register/verify',{method:'POST',body:{transaction:start.data.transaction,credential:serializeCredential(credential),name}});if(done.status!==200||!done.data?.ok)throw new Error(done.data?.detail||'Не удалось сохранить Passkey');toast('Face ID / Passkey добавлен');await loadBoot()}catch(e){if(e?.name!=='NotAllowedError')toast(e.message||'Регистрация отменена')}finally{button.disabled=false}}$('registerPasskeyBtn').onclick=registerPasskey;
function openQuoteEditor(row,item){row.innerHTML='<div class="quote-edit"><input class="input" value="'+esc(item.text)+'" maxlength="2000"><div class="toolbar" style="margin-top:8px"><button class="btn primary quote-save">Сохранить</button><button class="btn quote-cancel">Отмена</button></div></div>';const input=row.querySelector('input');input.focus();input.setSelectionRange(input.value.length,input.value.length);row.querySelector('.quote-cancel').onclick=loadQuotes;row.querySelector('.quote-save').onclick=async()=>{const text=input.value.trim();if(!text)return toast('Цитата не может быть пустой');const r=await api('quotes/'+encodeURIComponent(item.id),{method:'PUT',body:{text}});if(r.data?.ok){toast('Цитата обновлена');loadQuotes()}else toast(r.data?.detail||'Не удалось сохранить')}}
function renderQuotes(list=[]){$('quotesCount').textContent=list.length+' шт.';$('quoteList').innerHTML=list.map(x=>'<div class="quote" data-id="'+esc(x.id)+'"><div class="quote-text">'+esc(x.text)+'</div><div class="quote-actions"><button class="btn quote-edit-btn" type="button">Изменить</button><button class="btn danger quote-delete" type="button">Удалить</button></div></div>').join('')||'<div class="empty">Цитат пока нет. Добавьте первую — она сразу появится на сайте.</div>';if(list[0])$('siteQuote').value=list[0].text;document.querySelectorAll('#quoteList .quote').forEach((row,index)=>{const item=list[index];row.querySelector('.quote-edit-btn').onclick=()=>openQuoteEditor(row,item);row.querySelector('.quote-delete').onclick=()=>ask('Удалить эту цитату?',ok=>ok&&api('quotes/'+encodeURIComponent(item.id),{method:'DELETE'}).then(r=>{if(r.data?.ok){toast('Цитата удалена');renderQuotes(r.data.quotes||[])}else toast(r.data?.detail||'Ошибка')}))})}
function loadQuotes(){return api('quotes').then(r=>renderQuotes(r.data?.quotes||[]))}
$('quoteAdd').onclick=()=>{const text=$('quoteInput').value.trim();if(!text)return toast('Введите текст цитаты');api('quotes',{method:'POST',body:{text}}).then(r=>{if(r.data?.ok){$('quoteInput').value='';renderQuotes(r.data.quotes||[]);toast('Цитата добавлена');haptic('light')}else toast(r.data?.detail||'Ошибка')})};$('quoteInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('quoteAdd').click()}});$('copyDiag').onclick=()=>{const b=state.boot||{},safe={app_version:b.app_version,status:b.status,sources:(b.sources||[]).map(x=>({source_name:x.source_name,source_type:x.source_type,is_online:x.is_online,last_seen_at:x.last_seen_at,agent_version:x.agent_version})),metrics:b.metrics,services:b.services};copyText(JSON.stringify(safe,null,2)).then(()=>toast('Диагностика скопирована'))};
function setAvatarPreview(url){const value=url||'/assets/xass-app-icon-192.png';$('siteAvatarPreview').src=value;$('siteAvatarEditPreview').src=value}
function updateProfilePreview(){const name=$('siteName').value.trim()||'XASS',title=$('siteTitle').value.trim()||'Публичный профиль';$('sitePreviewName').textContent=name;$('sitePreviewTitle').textContent=title;$('stackCount').textContent=$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean).length+' шт.';$('linksCount').textContent=$('siteLinks').value.split('\n').map(x=>x.trim()).filter(Boolean).length+' шт.'}
function setProfileDirty(dirty){state.profileDirty=dirty;$('profileSaveState').textContent=dirty?'Есть изменения':'Сохранено';$('profileSaveState').classList.toggle('changed',dirty);$('saveDockText').textContent=dirty?'Изменения ещё не сохранены':'Все изменения сохранены';try{dirty?tg?.enableClosingConfirmation?.():tg?.disableClosingConfirmation?.()}catch(e){}}
function markProfileDirty(){setProfileDirty(true);updateProfilePreview()}
function renderSite(data){state.site=data;const p=data.profile||{};for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])$(id).value=p[key]||'';setAvatarPreview(p.avatar_url);$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');updateProfilePreview();setProfileDirty(false);renderProjects(data.projects||[]);loadQuotes();const url=data.public_url||location.origin+'/profile.php';$('homeOpenSite').href=url}
function loadSite(){api('site').then(r=>r.data?.ok?renderSite(r.data):toast(r.data?.detail||'Ошибка сайта'))}
function profilePayload(){return{name:$('siteName').value,username:$('siteUsername').value,title:$('siteTitle').value,bio:$('siteBio').value,telegram_url:$('siteTelegram').value,avatar_url:$('siteAvatar').value,quote:$('siteQuote').value,stack:$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean),links:$('siteLinks').value.split('\n').map(line=>{const parts=line.split('|');return{label:(parts.shift()||'').trim(),url:parts.join('|').trim()}}).filter(x=>x.label&&x.url)}}
$('saveProfileBtn').onclick=async function(){this.disabled=true;this.textContent='Сохраняю…';try{const r=await api('site/profile',{method:'POST',body:profilePayload()});if(r.data?.ok){state.site={...state.site,profile:r.data.profile};setProfileDirty(false);updateProfilePreview();toast('Изменения опубликованы');haptic('medium')}else toast(r.data?.detail||'Ошибка')}catch(e){toast('Не удалось сохранить изменения')}finally{this.disabled=false;this.textContent='Сохранить изменения'}};$('openSiteBtn').onclick=()=>{const url=state.site?.public_url||location.origin+'/profile.php';tg?.openLink?tg.openLink(url):window.open(url,'_blank')};
['siteName','siteUsername','siteTitle','siteBio','siteTelegram','siteAvatar','siteStack','siteLinks'].forEach(id=>$(id).addEventListener('input',markProfileDirty));
$('siteAvatar').addEventListener('input',()=>setAvatarPreview($('siteAvatar').value.trim()));$('chooseAvatarBtn').onclick=()=>$('siteAvatarFile').click();$('clearAvatarBtn').onclick=()=>{$('siteAvatar').value='';setAvatarPreview('');markProfileDirty()};$('siteAvatarFile').addEventListener('change',async()=>{const file=$('siteAvatarFile').files?.[0];if(!file)return;if(file.size>8*1024*1024)return toast('Файл больше 8 МБ');if(!/^image\/(jpeg|png|webp)$/i.test(file.type))return toast('Нужен JPG, PNG или WebP');const localUrl=URL.createObjectURL(file);setAvatarPreview(localUrl);$('chooseAvatarBtn').disabled=true;$('chooseAvatarBtn').textContent='Загружаю…';try{if(demo){$('siteAvatar').value='demo-avatar';toast('Демо: аватар выбран');return}const headers={'Content-Type':file.type};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/mini/site/avatar'),{method:'POST',headers,body:file,credentials:'include'}),data=await response.json();if(!response.ok||!data?.ok)throw new Error(data?.detail||'Ошибка загрузки');$('siteAvatar').value=data.avatar_url;setAvatarPreview(data.avatar_url);if(state.site)state.site.profile=data.profile;toast('Аватар опубликован');haptic('medium')}catch(e){setAvatarPreview(state.site?.profile?.avatar_url||'');toast(e.message||'Не удалось загрузить аватар')}finally{if(!demo)URL.revokeObjectURL(localUrl);$('chooseAvatarBtn').disabled=false;$('chooseAvatarBtn').textContent='Выбрать из галереи';$('siteAvatarFile').value=''}});
function renderProjects(list){state.site=state.site||{};state.site.projects=list;$('projectList').innerHTML=list.map(p=>'<div class="project"><div class="project-head"><div><div class="project-name">'+esc(p.title)+'</div><div class="project-desc">'+esc(p.description||p.subtitle||'Без описания')+'</div></div><span class="status">'+esc(p.status||'dev')+'</span></div><div class="device-actions"><button class="btn edit-project" data-id="'+esc(p.id)+'">Изменить</button><button class="btn danger delete-project" data-id="'+esc(p.id)+'">Удалить</button></div></div>').join('')||'<div class="empty">Проектов пока нет.</div>';document.querySelectorAll('.edit-project').forEach(b=>b.onclick=()=>openProject(list.find(p=>p.id===b.dataset.id)||{}));document.querySelectorAll('.delete-project').forEach(b=>b.onclick=()=>ask('Удалить проект?',ok=>ok&&api('site/projects/'+encodeURIComponent(b.dataset.id),{method:'DELETE'}).then(r=>r.data?.ok&&renderProjects(r.data.projects))))}
function openProject(p={}){const y=new Date().getFullYear();$('projectForm').style.display='block';$('projectFormTitle').textContent=p.id?'Редактировать проект':'Новый проект';$('projectId').value=p.id||'';$('projectTitle').value=p.title||'';$('projectStatus').value=p.status||'dev';$('projectSubtitle').value=p.subtitle||'';$('projectDescription').value=p.description||'';$('projectUrl').value=p.url||'';$('projectFrom').value=p.years?.from||y;$('projectTo').value=p.years?.to||y;$('projectTags').value=(p.tags||[]).join(', ');$('projectCover').value=p.cover?.src||'';$('projectFeatured').checked=!!p.featured;$('projectForm').scrollIntoView({behavior:'smooth'})}function projectPayload(){return{id:$('projectId').value,title:$('projectTitle').value,status:$('projectStatus').value,subtitle:$('projectSubtitle').value,description:$('projectDescription').value,url:$('projectUrl').value,year_from:Number($('projectFrom').value),year_to:Number($('projectTo').value),tags:$('projectTags').value.split(',').map(x=>x.trim()).filter(Boolean),cover_type:'image',cover_src:$('projectCover').value,featured:$('projectFeatured').checked}}$('newProjectBtn').onclick=()=>openProject();$('cancelProjectBtn').onclick=()=>{$('projectForm').style.display='none'};$('saveProjectBtn').onclick=function(){if(!$('projectTitle').value.trim())return toast('Введите название');this.disabled=true;api('site/projects',{method:'POST',body:projectPayload()}).then(r=>{this.disabled=false;if(r.data?.ok){renderProjects(r.data.projects);$('projectForm').style.display='none';toast('Проект сохранён')}else toast(r.data?.detail||'Ошибка')})};
$('logoutBtn').onclick=()=>pwaApi('logout',{method:'POST'}).then(()=>location.reload());
function loginReadiness(config={}){const req=config.requirements||{},labels={bot_token:'BOT_TOKEN найден',bot_username:'Бот определён',owner_user_id:'OWNER_USER_ID настроен',https:'HTTPS доступен'},rows=Object.keys(labels).map(key=>'<div class="ready-row '+(req[key]?'ok':'bad')+'"><span class="ready-icon">'+(req[key]?'✓':'!')+'</span><span>'+labels[key]+'</span></div>').join('');return'<div class="login-readiness"><h3>Локальная готовность XASS</h3><p>Это отдельная проверка сервера. Состояние /setdomain может подтвердить только Telegram.</p>'+rows+'</div>'}
async function initPwa(){try{const pairToken=new URLSearchParams(location.hash.replace(/^#/,''));const token=pairToken.get('pair')||'';if(token){const exchange=await pwaApi('exchange',{method:'POST',body:{token}});history.replaceState(null,'',location.pathname+location.search);if(exchange.status!==200||!exchange.data?.ok)throw new Error(exchange.data?.detail||'Одноразовая ссылка недействительна');return loadBoot()}const r=await pwaApi('config'),config=r.data||{};state.pwaConfig=config;if(config.authenticated)return loadBoot();$('loader').style.display='none';$('login').style.display='block';$('passkeyLoginBtn').style.display=config.passkey_available?'block':'none';$('passkeyLoginBtn').onclick=async()=>{const button=$('passkeyLoginBtn');button.disabled=true;try{await passkeyAuthenticate('login');$('login').style.display='none';$('loader').style.display='flex';await loadBoot()}catch(e){if(e?.name!=='NotAllowedError')toast(e.message||'Face ID не подтвердил вход')}finally{button.disabled=false}};if(!config.login_ready){$('telegramWidget').innerHTML=loginReadiness(config)+'<div class="ios-help">Откройте свежую одноразовую ссылку, созданную внутри Telegram Mini App — для неё BotFather не нужен.</div>';return}window.onTelegramAuth=async user=>{try{const login=await pwaApi('login',{method:'POST',body:user});if(login.status!==200||!login.data?.ok)throw new Error(login.data?.detail||'Вход отклонён');$('login').style.display='none';$('loader').style.display='flex';await loadBoot()}catch(e){toast(e.message)}};const script=document.createElement('script');script.async=true;script.src='https://telegram.org/js/telegram-widget.js?22';script.dataset.telegramLogin=config.bot_username;script.dataset.size='large';script.dataset.userpic='false';script.dataset.radius='12';script.dataset.onauth='onTelegramAuth(user)';script.onerror=()=>{$('telegramWidget').innerHTML='<div class="login-readiness"><h3>Виджет Telegram не загрузился</h3><p>Вернитесь в Telegram Mini App и создайте одноразовую ссылку для iPhone. Она работает без Login Widget и проверки /setdomain.</p></div>'};$('telegramWidget').appendChild(script)}catch(e){showDeny('Не удалось войти: '+e.message)}}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
demo||initData?loadBoot():initPwa();
})();
</script>
</body></html>
